CREATE TABLE IF NOT EXISTS app_sessions(sid VARCHAR(128) PRIMARY KEY,data MEDIUMTEXT NOT NULL,expires_at DATETIME NOT NULL,INDEX idx_session_expiry(expires_at));
CREATE TABLE IF NOT EXISTS auth_limits(bucket_key CHAR(64) PRIMARY KEY,attempts INT UNSIGNED NOT NULL DEFAULT 1,expires_at DATETIME NOT NULL,INDEX idx_auth_expiry(expires_at));
CREATE TABLE IF NOT EXISTS workshop_revisions(workshop_id INT UNSIGNED PRIMARY KEY,proposal JSON NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',note VARCHAR(500) NULL,reviewed_by INT UNSIGNED NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(workshop_id) REFERENCES partner_workshops(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS user_notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,order_id INT UNSIGNED NULL,title VARCHAR(200) NOT NULL,message VARCHAR(500) NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_notice_user(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(order_id) REFERENCES service_orders(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS support_tickets(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,message VARCHAR(2000) NOT NULL,status ENUM('open','closed') NOT NULL DEFAULT 'open',admin_reply VARCHAR(2000) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS support_conversations(user_id INT UNSIGNED PRIMARY KEY,messages JSON NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
